insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('prima-laris', 'Prima-Laris 240 OD', 'herbisida', '500 ml', 'images/produk/prima-laris.webp', 'Herbisida sistemik purna tumbuh untuk mengendalikan gulma pada tanaman jagung.', 'Atrazin 180 g/L, Mesotrion 40 g/L, Nikosulfuron 20 g/L', 'Gulma berdaun lebar dan rumput pada tanaman jagung', 'Herbisida sistemik purna tumbuh berbentuk pekatan berwarna putih susu. Bekerja setelah gulma tumbuh, diserap melalui daun dan disebarkan ke seluruh bagian gulma sehingga mati sampai ke akar. Cocok digunakan pada budidaya tanaman jagung.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('gisentro', 'Gisentro 560 SC + Surfaktan', 'herbisida', '400 ml + 250 ml', 'images/produk/gisentro.webp', 'Herbisida sistemik pra & purna tumbuh, kendalikan gulma daun lebar dan rumput di jagung.', 'Atrazin 500 g/L + Mesotrion 60 g/L', 'Gulma berdaun lebar dan rumput pada tanaman jagung', 'Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi yang dapat larut dalam air. Dilengkapi Surfaktan sebagai bahan perata yang membantu meratakan semprotan herbisida di permukaan daun gulma sasaran, sehingga daya kerjanya lebih efektif.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('atradex', 'Atradex 550 SC + Surfaktan', 'herbisida', '500 ml + 200 ml', 'images/produk/atradex.webp', 'Herbisida sistemik pra & purna tumbuh untuk gulma daun lebar dan berdaun sempit pada jagung.', 'Mesotrion 50 g/L + Atrazin 500 g/L', 'Gulma berdaun lebar dan berdaun sempit pada tanaman jagung', 'Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih. Paket sudah termasuk Surfaktan untuk mendapatkan kualitas penyemprotan maksimal serta perhatian penuh pada petunjuk penggunaan di label.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('cornelia', 'Cornelia 265/35 OD + Surfaktan', 'herbisida', '500 ml', 'images/produk/cornelia.webp', 'Paket herbisida sistemik pratumbuh & purna tumbuh, larut dalam minyak, untuk tanaman jagung.', 'Atrazin 265 g/L + Nikosulfuron 35 g/L', 'Gulma berdaun lebar dan golongan rumput pada tanaman jagung', 'Herbisida sistemik selektif pratumbuh dan purna tumbuh berbentuk larutan dalam minyak. Satu paket dengan Santer sebagai bahan perekat, perata, penembus, dan emulgator untuk membantu daya kerja herbisida lebih maksimal pada gulma sasaran.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('tandem', 'Tandem 325 SC', 'fungisida', '100–250 ml', 'images/produk/tandem.webp', 'Fungisida sistemik protektif-kuratif untuk mengendalikan penyakit pada padi, kakao & jagung.', 'Azoksistrobin 200 g/L + Difenokonazol 125 g/L', 'Penyakit pada tanaman padi, kakao, dan jagung', 'Fungisida sistemik, protektif, dan kuratif berbentuk pekatan suspensi yang larut dalam air. Bekerja mencegah sekaligus mengobati serangan penyakit pada tanaman, cocok digunakan sebagai bagian dari program perlindungan tanaman padi, kakao, maupun jagung.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('abacel-100', 'Abacel 18 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida racun kontak & lambung untuk mengendalikan thrips dan ulat grayak.', 'Abamektin 18 g/L', 'Thrips dan ulat grayak pada cabai, bawang merah, tomat, dan padi', 'Insektisida berbahan aktif abamektin yang bekerja sebagai racun kontak, lambung, dan translaminar (meresap ke jaringan tanaman). Efektif mengendalikan hama thrips dan ulat grayak pada tanaman cabai, bawang merah, tomat, dan padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('abacel-250', 'Abacel 18 EC 250ml', 'insektisida', '250 ml', NULL, 'Insektisida racun kontak & lambung untuk mengendalikan thrips dan ulat grayak.', 'Abamektin 18 g/L', 'Thrips dan ulat grayak pada cabai, bawang merah, tomat, dan padi', 'Insektisida berbahan aktif abamektin yang bekerja sebagai racun kontak, lambung, dan translaminar (meresap ke jaringan tanaman). Efektif mengendalikan hama thrips dan ulat grayak pada tanaman cabai, bawang merah, tomat, dan padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('abacel-500', 'Abacel 18 EC 500ml', 'insektisida', '500 ml', NULL, 'Insektisida racun kontak & lambung untuk mengendalikan thrips dan ulat grayak.', 'Abamektin 18 g/L', 'Thrips dan ulat grayak pada cabai, bawang merah, tomat, dan padi', 'Insektisida berbahan aktif abamektin yang bekerja sebagai racun kontak, lambung, dan translaminar (meresap ke jaringan tanaman). Efektif mengendalikan hama thrips dan ulat grayak pada tanaman cabai, bawang merah, tomat, dan padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('emacel-100', 'Emacel 30 EC 100ml', 'insektisida', '100 ml', 'images/produk/emacel-100.webp', 'Insektisida racun kontak & lambung untuk mengendalikan ulat grayak dan pengorok daun.', 'Emamektin Benzoat 30 g/L', 'Ulat grayak dan pengorok daun pada bawang merah, padi, jagung, cabai, dan kubis', 'Insektisida berbahan aktif emamektin benzoat, bekerja sebagai racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan. Efektif mengendalikan hama ulat grayak dan pengorok daun pada tanaman bawang merah, padi, jagung, cabai, dan kubis.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('emacel-250', 'Emacel 30 EC 250ml', 'insektisida', '250 ml', 'images/produk/emacel-250.webp', 'Insektisida racun kontak & lambung untuk mengendalikan ulat grayak dan pengorok daun.', 'Emamektin Benzoat 30 g/L', 'Ulat grayak dan pengorok daun pada bawang merah, padi, jagung, cabai, dan kubis', 'Insektisida berbahan aktif emamektin benzoat, bekerja sebagai racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan. Efektif mengendalikan hama ulat grayak dan pengorok daun pada tanaman bawang merah, padi, jagung, cabai, dan kubis.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('emacel-500', 'Emacel 30 EC 500ml', 'insektisida', '500 ml', 'images/produk/emacel-500.webp', 'Insektisida racun kontak & lambung untuk mengendalikan ulat grayak dan pengorok daun.', 'Emamektin Benzoat 30 g/L', 'Ulat grayak dan pengorok daun pada bawang merah, padi, jagung, cabai, dan kubis', 'Insektisida berbahan aktif emamektin benzoat, bekerja sebagai racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan. Efektif mengendalikan hama ulat grayak dan pengorok daun pada tanaman bawang merah, padi, jagung, cabai, dan kubis.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('score-80', 'Score 250 EC 80ml', 'fungisida', '80 ml', 'images/produk/score-80.webp', 'Fungisida sistemik untuk mengendalikan penyakit bercak daun dan busuk phytophthora.', 'Difenokonazol 250 g/L', 'Bercak daun dan busuk phytophthora pada padi, cabai, dan tanaman hortikultura lainnya', 'Fungisida sistemik produksi Syngenta dengan bahan aktif difenokonazol yang juga berperan sebagai zat pengatur tumbuh (ZPT). Bekerja masuk ke jaringan tanaman untuk mengendalikan penyakit akibat jamur, terutama bercak daun dan busuk phytophthora, pada padi, cabai, dan berbagai tanaman hortikultura lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('score-250', 'Score 250 EC 250ml', 'fungisida', '250 ml', NULL, 'Fungisida sistemik untuk mengendalikan penyakit bercak daun dan busuk phytophthora.', 'Difenokonazol 250 g/L', 'Bercak daun dan busuk phytophthora pada padi, cabai, dan tanaman hortikultura lainnya', 'Fungisida sistemik produksi Syngenta dengan bahan aktif difenokonazol yang juga berperan sebagai zat pengatur tumbuh (ZPT). Bekerja masuk ke jaringan tanaman untuk mengendalikan penyakit akibat jamur, terutama bercak daun dan busuk phytophthora, pada padi, cabai, dan berbagai tanaman hortikultura lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('prevathon-100', 'Prevathon 50 SC 100ml', 'insektisida', '100 ml', 'images/produk/prevathon-100.webp', 'Insektisida sistemik translaminar untuk mengendalikan penggerek batang padi dan ulat grayak.', 'Klorantraniliprol 50 g/L', 'Penggerek batang padi (sundep), ulat grayak, dan hama perusak daun', 'Insektisida sistemik racun kontak, lambung, dan syaraf yang bekerja secara translaminar (meresap ke jaringan tanaman). Sangat efektif mengendalikan hama penggerek batang padi (sundep), ulat grayak, dan berbagai hama perusak daun pada padi, cabai, jagung, dan tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('prevathon-250', 'Prevathon 50 SC 250ml', 'insektisida', '250 ml', 'images/produk/prevathon-250.webp', 'Insektisida sistemik translaminar untuk mengendalikan penggerek batang padi dan ulat grayak.', 'Klorantraniliprol 50 g/L', 'Penggerek batang padi (sundep), ulat grayak, dan hama perusak daun', 'Insektisida sistemik racun kontak, lambung, dan syaraf yang bekerja secara translaminar (meresap ke jaringan tanaman). Sangat efektif mengendalikan hama penggerek batang padi (sundep), ulat grayak, dan berbagai hama perusak daun pada padi, cabai, jagung, dan tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('prevathon-500', 'Prevathon 50 SC 500ml', 'insektisida', '500 ml', NULL, 'Insektisida sistemik translaminar untuk mengendalikan penggerek batang padi dan ulat grayak.', 'Klorantraniliprol 50 g/L', 'Penggerek batang padi (sundep), ulat grayak, dan hama perusak daun', 'Insektisida sistemik racun kontak, lambung, dan syaraf yang bekerja secara translaminar (meresap ke jaringan tanaman). Sangat efektif mengendalikan hama penggerek batang padi (sundep), ulat grayak, dan berbagai hama perusak daun pada padi, cabai, jagung, dan tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('amistartop-100', 'Amistartop 325 SC 100ml', 'fungisida', '100 ml', NULL, 'Fungisida sistemik untuk mengendalikan berbagai penyakit jamur pada tanaman.', 'Azoksistrobin 200 g/L + Difenokonazol 125 g/L', 'Bercak daun, karat, dan berbagai penyakit jamur pada padi, jagung, cabai, kopi, kakao, dan tanaman lain', 'Fungisida sistemik produksi Syngenta dengan kombinasi dua bahan aktif (azoksistrobin dan difenokonazol) yang saling melengkapi cara kerjanya, sehingga lebih efektif mengendalikan jamur patogen. Digunakan luas pada padi, jagung, cabai, kopi, kakao, dan berbagai tanaman hortikultura maupun perkebunan lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('amistartop-250', 'Amistartop 325 SC 250ml', 'fungisida', '250 ml', NULL, 'Fungisida sistemik untuk mengendalikan berbagai penyakit jamur pada tanaman.', 'Azoksistrobin 200 g/L + Difenokonazol 125 g/L', 'Bercak daun, karat, dan berbagai penyakit jamur pada padi, jagung, cabai, kopi, kakao, dan tanaman lain', 'Fungisida sistemik produksi Syngenta dengan kombinasi dua bahan aktif (azoksistrobin dan difenokonazol) yang saling melengkapi cara kerjanya, sehingga lebih efektif mengendalikan jamur patogen. Digunakan luas pada padi, jagung, cabai, kopi, kakao, dan berbagai tanaman hortikultura maupun perkebunan lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('stadium-100', 'Stadium 18 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida & akarisida untuk penggerek batang padi, wereng coklat, dan tungau.', 'Abamektin 18 g/L', 'Penggerek batang padi (sundep/beluk), wereng coklat, tungau, dan pengorok daun', 'Insektisida yang bekerja secara kontak, lambung, dan sistemik translaminar, sekaligus bersifat akarisida (pembasmi tungau). Efektif mengendalikan hama tersembunyi seperti penggerek batang padi, wereng coklat, hama putih palsu, tungau, dan pengorok daun.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('stadium-200', 'Stadium 18 EC 200ml', 'insektisida', '200 ml', NULL, 'Insektisida & akarisida untuk penggerek batang padi, wereng coklat, dan tungau.', 'Abamektin 18 g/L', 'Penggerek batang padi (sundep/beluk), wereng coklat, tungau, dan pengorok daun', 'Insektisida yang bekerja secara kontak, lambung, dan sistemik translaminar, sekaligus bersifat akarisida (pembasmi tungau). Efektif mengendalikan hama tersembunyi seperti penggerek batang padi, wereng coklat, hama putih palsu, tungau, dan pengorok daun.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('stadium-500', 'Stadium 18 EC 500ml', 'insektisida', '500 ml', NULL, 'Insektisida & akarisida untuk penggerek batang padi, wereng coklat, dan tungau.', 'Abamektin 18 g/L', 'Penggerek batang padi (sundep/beluk), wereng coklat, tungau, dan pengorok daun', 'Insektisida yang bekerja secara kontak, lambung, dan sistemik translaminar, sekaligus bersifat akarisida (pembasmi tungau). Efektif mengendalikan hama tersembunyi seperti penggerek batang padi, wereng coklat, hama putih palsu, tungau, dan pengorok daun.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('curacron-100', 'Curacron 500 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida & akarisida multifungsi untuk kutu daun, ulat grayak, dan thrips.', 'Profenofos 500 g/L', 'Kutu daun, ulat grayak, ulat tanah, lalat buah, penggerek daun/batang/buah, dan thrips', 'Insektisida produksi Syngenta yang bekerja sebagai racun kontak dan lambung dengan efek translaminar, sehingga mampu menjangkau hama yang bersembunyi di balik daun. Mengendalikan berbagai hama pada tanaman cabai, bawang merah, tomat, semangka, kubis, dan tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('curacron-250', 'Curacron 500 EC 250ml', 'insektisida', '250 ml', NULL, 'Insektisida & akarisida multifungsi untuk kutu daun, ulat grayak, dan thrips.', 'Profenofos 500 g/L', 'Kutu daun, ulat grayak, ulat tanah, lalat buah, penggerek daun/batang/buah, dan thrips', 'Insektisida produksi Syngenta yang bekerja sebagai racun kontak dan lambung dengan efek translaminar, sehingga mampu menjangkau hama yang bersembunyi di balik daun. Mengendalikan berbagai hama pada tanaman cabai, bawang merah, tomat, semangka, kubis, dan tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('decis-50', 'Decis 25 EC 50ml', 'insektisida', '50 ml', NULL, 'Insektisida racun kontak & lambung untuk ulat grayak, belalang, kutu, dan thrips.', 'Deltametrin 25 g/L', 'Ulat grayak, belalang, kutu, thrips, dan lalat pada berbagai tanaman', 'Insektisida produksi Bayer yang bekerja sebagai racun kontak dan lambung dengan efek knock-down cepat serta efek anti-feeding (membuat hama berhenti makan). Digunakan luas pada bawang merah, cabai, jagung, kacang panjang, padi, dan banyak tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('decis-100', 'Decis 25 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida racun kontak & lambung untuk ulat grayak, belalang, kutu, dan thrips.', 'Deltametrin 25 g/L', 'Ulat grayak, belalang, kutu, thrips, dan lalat pada berbagai tanaman', 'Insektisida produksi Bayer yang bekerja sebagai racun kontak dan lambung dengan efek knock-down cepat serta efek anti-feeding (membuat hama berhenti makan). Digunakan luas pada bawang merah, cabai, jagung, kacang panjang, padi, dan banyak tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('decis-250', 'Decis 25 EC 250ml', 'insektisida', '250 ml', NULL, 'Insektisida racun kontak & lambung untuk ulat grayak, belalang, kutu, dan thrips.', 'Deltametrin 25 g/L', 'Ulat grayak, belalang, kutu, thrips, dan lalat pada berbagai tanaman', 'Insektisida produksi Bayer yang bekerja sebagai racun kontak dan lambung dengan efek knock-down cepat serta efek anti-feeding (membuat hama berhenti makan). Digunakan luas pada bawang merah, cabai, jagung, kacang panjang, padi, dan banyak tanaman lainnya.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('demolish-200', 'Demolish 18 EC 200ml', 'insektisida', '200 ml', 'images/produk/demolish-200.webp', 'Insektisida racun kontak & lambung untuk berbagai hama sayuran dan perkebunan.', 'Abamektin 18 g/L', 'Hama pada cabai, bawang merah, kubis, padi, kentang, dan kelapa sawit', 'Insektisida racun kontak dan lambung berwarna coklat kehitaman, berbentuk pekatan yang dapat diemulsikan. Digunakan untuk mengendalikan hama pada tanaman cabai, bawang merah, kubis, padi, kentang, dan kelapa sawit.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('glufo-1l', 'Glufo 150 SL 1 Liter', 'herbisida', '1 liter', 'images/produk/glufo-1l.webp', 'Herbisida sistemik purna tumbuh non-selektif untuk gulma di perkebunan sawit & kakao.', 'Amonium Glufosinat 150 g/L', 'Gulma berdaun lebar dan berdaun sempit pada kelapa sawit (TBM) dan kakao (TBM)', 'Herbisida sistemik purna tumbuh non-selektif berbentuk pekatan berwarna biru kehijauan yang dapat larut dalam air. Digunakan untuk mengendalikan gulma berdaun lebar maupun berdaun sempit pada areal perkebunan kelapa sawit dan kakao yang belum menghasilkan (TBM).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('roundup-4l', 'Roundup 486 SL 4 Liter', 'herbisida', '4 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma umum di berbagai perkebunan.', 'IPA Glifosat 486 g/L (setara Glifosat 360 g/L)', 'Gulma umum pada akasia, cengkih, kakao, karet, kedelai, kelapa, kelapa sawit, kopi, jagung, dan teh', 'Herbisida sistemik purna tumbuh dengan teknologi Biosorb, berbentuk larutan dalam air. Digunakan luas untuk mengendalikan gulma umum pada berbagai tanaman perkebunan seperti akasia, cengkih, kakao, karet, kelapa sawit, kopi, dan teh. Catatan: tidak untuk digunakan pada tanaman padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('bentop-5l', 'Bentop 276 SL 5 Liter', 'herbisida', '5 liter', NULL, 'Herbisida kontak purna tumbuh untuk gulma umum pada kelapa sawit dan jagung.', 'Parakuat Diklorida 276 g/L (setara ion parakuat 200 g/L)', 'Gulma umum pada kelapa sawit (TM) dan jagung (tanpa olah tanah)', 'Herbisida terbatas golongan Bipyridylium yang bekerja secara kontak purna tumbuh, berbentuk larutan dalam air. Digunakan untuk mengendalikan gulma umum pada tanaman kelapa sawit menghasilkan (TM) dan jagung sistem tanpa olah tanah (TOT). Produk ini hanya boleh digunakan oleh pengguna bersertifikat.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('gempur-5l', 'Gempur 480 SL 5 Liter', 'herbisida', '5 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma di lahan perkebunan & persiapan lahan.', 'Isopropil Amina Glifosat 480 g/L (setara Glifosat 356 g/L)', 'Gulma pada hutan tanaman industri, kakao, karet, kelapa sawit, kopi, teh, dan persiapan lahan jagung (TOT)', 'Herbisida sistemik purna tumbuh berbentuk larutan yang dapat larut dalam air, berwarna kuning kecoklatan. Digunakan untuk mengendalikan gulma pada hutan tanaman industri (Acacia mangium), perkebunan kakao, karet, kelapa sawit, kopi, teh, serta persiapan lahan budidaya jagung tanpa olah tanah.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('gramoxone-5l', 'Gramoxone 276 SL 5 Liter', 'herbisida', '5 liter', NULL, 'Herbisida kontak purna tumbuh spektrum luas untuk berbagai jenis tanaman.', 'Parakuat Diklorida 276 g/L (setara ion parakuat 200 g/L)', 'Anakan sawit liar, gulma berdaun lebar, sempit, dan teki pada berbagai tanaman', 'Herbisida produksi Syngenta yang bekerja secara kontak purna tumbuh, berbentuk larutan dalam air berwarna hijau tua. Mengendalikan anakan sawit liar serta gulma berdaun lebar, sempit, dan teki di lahan tanpa tanaman maupun di sela tanaman perkebunan (karet, kelapa sawit, kopi, tebu, teh) dan tanaman pangan (jagung, padi gogo, kedelai, kentang, kubis, tomat) serta tanaman buah. Hanya digunakan oleh pengguna bersertifikat.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('dosdet-500', 'Dosdet 500 gram', 'zpt', '500 gram', NULL, 'Pupuk daun / ZPT untuk menyuburkan tanaman dan mencegah kerontokan bunga & buah.', 'Formula pupuk daun / zat pengatur tumbuh (komposisi lengkap tertera pada label kemasan)', 'Tanaman buah, sayur, dan perkebunan seperti mangga, kopi, tomat, melon, kubis, dan sawit', 'Produk penyubur tanaman yang bekerja menyuburkan daun, bunga, dan buah, mencegah daun keriting/layu/kuning, merangsang pertumbuhan tunas baru, serta mencegah kerontokan bunga dan buah agar hasil panen lebih optimal. Cocok digunakan pada berbagai tanaman buah, sayur, dan perkebunan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('ultradap-1kg', 'Ultradap 1 Kg', 'pupuk', '1 kg', NULL, 'Pupuk untuk mendukung pertumbuhan dan hasil panen berbagai tanaman hortikultura.', 'Formula pupuk (komposisi lengkap tertera pada label kemasan)', 'Tanaman hortikultura seperti cabai, tomat, semangka, melon, dan buah-buahan', 'Pupuk produksi merek Pak Tani yang digunakan untuk mendukung pertumbuhan dan hasil panen berbagai tanaman hortikultura seperti cabai, tomat, semangka, melon, dan tanaman buah lainnya. Cek label kemasan untuk dosis dan cara aplikasi yang dianjurkan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('dangke-100', 'Dangke 40 WP 100gr', 'insektisida', '100 gram', NULL, 'Insektisida tepung racun kontak & lambung untuk hama ulat pada berbagai tanaman.', 'Metomil 40%', 'Hama ulat pada bawang merah, kedelai, cabai, kacang panjang, kakao, tomat, kubis, dan kelapa sawit', 'Insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat disuspensikan (wettable powder) berwarna putih. Digunakan untuk mengendalikan hama ulat pada tanaman bawang merah, kedelai, cabai, kacang panjang, kakao, tomat, kacang hijau, kubis, dan kelapa sawit.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('regent-50', 'Regent 50 SC 50ml', 'insektisida', '50 ml', NULL, 'Insektisida & ZPT sistemik untuk ulat gantung, thrips, wereng, dan kutu daun.', 'Fipronil 50 g/L', 'Ulat gantung, thrips, kutu daun, wereng coklat, walang sangit, belalang pada cabai, jagung, jeruk, kacang panjang, kelapa sawit, kentang, kubis, kedelai, dan padi', 'Insektisida sistemik produksi BASF berbentuk pekatan suspensi berwarna putih, bekerja sebagai racun kontak dan lambung. Selain mengendalikan hama, Regent 50 SC juga berfungsi sebagai Zat Pengatur Tumbuh (ZPT) yang merangsang pertumbuhan akar dan membuat daun lebih hijau. Efektif untuk berbagai hama pada tanaman cabai, jagung, jeruk, kacang panjang, kelapa sawit, kentang, kubis, semangka, kedelai, tebu, dan padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('regent-100', 'Regent 50 SC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida & ZPT sistemik untuk ulat gantung, thrips, wereng, dan kutu daun.', 'Fipronil 50 g/L', 'Ulat gantung, thrips, kutu daun, wereng coklat, walang sangit, belalang pada cabai, jagung, jeruk, kacang panjang, kelapa sawit, kentang, kubis, kedelai, dan padi', 'Insektisida sistemik produksi BASF berbentuk pekatan suspensi berwarna putih, bekerja sebagai racun kontak dan lambung. Selain mengendalikan hama, Regent 50 SC juga berfungsi sebagai Zat Pengatur Tumbuh (ZPT) yang merangsang pertumbuhan akar dan membuat daun lebih hijau. Efektif untuk berbagai hama pada tanaman cabai, jagung, jeruk, kacang panjang, kelapa sawit, kentang, kubis, semangka, kedelai, tebu, dan padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('regent-250', 'Regent 50 SC 250ml', 'insektisida', '250 ml', NULL, 'Insektisida & ZPT sistemik untuk ulat gantung, thrips, wereng, dan kutu daun.', 'Fipronil 50 g/L', 'Ulat gantung, thrips, kutu daun, wereng coklat, walang sangit, belalang pada cabai, jagung, jeruk, kacang panjang, kelapa sawit, kentang, kubis, kedelai, dan padi', 'Insektisida sistemik produksi BASF berbentuk pekatan suspensi berwarna putih, bekerja sebagai racun kontak dan lambung. Selain mengendalikan hama, Regent 50 SC juga berfungsi sebagai Zat Pengatur Tumbuh (ZPT) yang merangsang pertumbuhan akar dan membuat daun lebih hijau. Efektif untuk berbagai hama pada tanaman cabai, jagung, jeruk, kacang panjang, kelapa sawit, kentang, kubis, semangka, kedelai, tebu, dan padi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('marshal-100', 'Marshal 200 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida sistemik untuk ulat kantong, wereng, kutu daun, thrips, dan tungau.', 'Karbosulfan 200 g/L', 'Ulat kantong, wereng, kutu daun, thrips, penggerek batang, dan tungau pada cabai, bawang merah, kedelai, kelapa sawit, jeruk, kakao, kapas, dan ketimun', 'Insektisida sistemik produksi FMC berbentuk pekatan yang dapat diemulsikan berwarna coklat, bekerja sebagai racun kontak dan lambung. Cepat menghentikan aktivitas makan hama sehingga mengurangi kerusakan tanaman, dan kompatibel dicampur dengan sebagian besar fungisida dan insektisida lain.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('marshal-500', 'Marshal 200 EC 500ml', 'insektisida', '500 ml', NULL, 'Insektisida sistemik untuk ulat kantong, wereng, kutu daun, thrips, dan tungau.', 'Karbosulfan 200 g/L', 'Ulat kantong, wereng, kutu daun, thrips, penggerek batang, dan tungau pada cabai, bawang merah, kedelai, kelapa sawit, jeruk, kakao, kapas, dan ketimun', 'Insektisida sistemik produksi FMC berbentuk pekatan yang dapat diemulsikan berwarna coklat, bekerja sebagai racun kontak dan lambung. Cepat menghentikan aktivitas makan hama sehingga mengurangi kerusakan tanaman, dan kompatibel dicampur dengan sebagian besar fungisida dan insektisida lain.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('antracol-250', 'Antracol 70 WP 250gr', 'fungisida', '250 gram', 'https://www.bayer.com/sites/default/files/2021-03/Antracol_ps-new-web480x480.png?imbypass=true', 'Fungisida kontak protektif untuk penyakit jamur pada berbagai tanaman.', 'Propineb 70%', 'Bercak daun, busuk hitam, bercak ungu, antraknosa, bulai, dan embun tepung pada cabai, bawang merah, tomat, jagung, kentang, kedelai, kubis, dan padi', 'Fungisida kontak protektif produksi Bayer berbentuk tepung berwarna krem yang dapat disuspensikan dalam air. Mengandung tambahan unsur zinc yang membantu tanaman lebih sehat. Bekerja mencegah spora jamur berkecambah dan menginfeksi jaringan tanaman, cocok digunakan untuk tanaman sayuran, buah, maupun perkebunan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('antracol-500', 'Antracol 70 WP 500gr', 'fungisida', '500 gram', 'https://www.bayer.com/sites/default/files/2021-03/Antracol_ps-new-web480x480.png?imbypass=true', 'Fungisida kontak protektif untuk penyakit jamur pada berbagai tanaman.', 'Propineb 70%', 'Bercak daun, busuk hitam, bercak ungu, antraknosa, bulai, dan embun tepung pada cabai, bawang merah, tomat, jagung, kentang, kedelai, kubis, dan padi', 'Fungisida kontak protektif produksi Bayer berbentuk tepung berwarna krem yang dapat disuspensikan dalam air. Mengandung tambahan unsur zinc yang membantu tanaman lebih sehat. Bekerja mencegah spora jamur berkecambah dan menginfeksi jaringan tanaman, cocok digunakan untuk tanaman sayuran, buah, maupun perkebunan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('antracol-1000', 'Antracol 70 WP 1kg', 'fungisida', '1 kg', 'https://www.bayer.com/sites/default/files/2021-03/Antracol_ps-new-web480x480.png?imbypass=true', 'Fungisida kontak protektif untuk penyakit jamur pada berbagai tanaman.', 'Propineb 70%', 'Bercak daun, busuk hitam, bercak ungu, antraknosa, bulai, dan embun tepung pada cabai, bawang merah, tomat, jagung, kentang, kedelai, kubis, dan padi', 'Fungisida kontak protektif produksi Bayer berbentuk tepung berwarna krem yang dapat disuspensikan dalam air. Mengandung tambahan unsur zinc yang membantu tanaman lebih sehat. Bekerja mencegah spora jamur berkecambah dan menginfeksi jaringan tanaman, cocok digunakan untuk tanaman sayuran, buah, maupun perkebunan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('matador-50', 'Matador 25 EC 50ml', 'insektisida', '50 ml', NULL, 'Insektisida knockdown cepat untuk ulat grayak, wereng, dan walang sangit.', 'Lambda Sihalotrin 25 g/L', 'Ulat grayak, wereng, walang sangit, gasir, orong-orong pada bawang merah, bawang putih, cabai, jagung, jeruk, dan kacang panjang', 'Insektisida golongan piretroid produksi Syngenta, berbentuk pekatan berwarna kuning jerami jernih yang dapat diemulsikan. Bekerja sebagai racun kontak dan lambung dengan efek knockdown cepat, melumpuhkan hama dalam hitungan menit. Cocok untuk hama perusak daun pada berbagai tanaman sayuran dan pangan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('matador-80', 'Matador 25 EC 80ml', 'insektisida', '80 ml', NULL, 'Insektisida knockdown cepat untuk ulat grayak, wereng, dan walang sangit.', 'Lambda Sihalotrin 25 g/L', 'Ulat grayak, wereng, walang sangit, gasir, orong-orong pada bawang merah, bawang putih, cabai, jagung, jeruk, dan kacang panjang', 'Insektisida golongan piretroid produksi Syngenta, berbentuk pekatan berwarna kuning jerami jernih yang dapat diemulsikan. Bekerja sebagai racun kontak dan lambung dengan efek knockdown cepat, melumpuhkan hama dalam hitungan menit. Cocok untuk hama perusak daun pada berbagai tanaman sayuran dan pangan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('matador-250', 'Matador 25 EC 250ml', 'insektisida', '250 ml', NULL, 'Insektisida knockdown cepat untuk ulat grayak, wereng, dan walang sangit.', 'Lambda Sihalotrin 25 g/L', 'Ulat grayak, wereng, walang sangit, gasir, orong-orong pada bawang merah, bawang putih, cabai, jagung, jeruk, dan kacang panjang', 'Insektisida golongan piretroid produksi Syngenta, berbentuk pekatan berwarna kuning jerami jernih yang dapat diemulsikan. Bekerja sebagai racun kontak dan lambung dengan efek knockdown cepat, melumpuhkan hama dalam hitungan menit. Cocok untuk hama perusak daun pada berbagai tanaman sayuran dan pangan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('topsin-100', 'Topsin M 70 WP 100gr', 'fungisida', '100 gram', NULL, 'Fungisida sistemik untuk penyakit jamur pada padi, cabai, dan bawang.', 'Metil Tiofanat 70%', 'Blas padi, bercak ungu, antraknosa, dan bercak daun pada padi, bawang merah, bawang putih, cabai, kacang hijau, kacang tanah, dan tembakau', 'Fungisida sistemik produksi Petrokimia Kayaku berbentuk tepung berwarna putih kecoklatan yang dapat disuspensikan. Mudah diserap dan disebarkan ke seluruh jaringan tanaman untuk menghambat pertumbuhan cendawan. Digunakan untuk mengendalikan berbagai penyakit jamur pada tanaman pangan, sayuran, dan perkebunan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('mipcin-100', 'Mipcinta 50 WP 100gr', 'insektisida', '100 gram', NULL, 'Insektisida untuk wereng coklat, walang sangit, dan hama penting tanaman padi.', 'MIPC (Isoprocarb) 50%', 'Wereng coklat, wereng hijau, walang sangit, kutu putih, dan penghisap daun pada padi, jagung, kedelai, kakao, kopi, lada, lamtoro, dan teh', 'Insektisida produksi Petrokimia Kayaku berbentuk tepung putih susu yang dapat disuspensikan (wettable powder). Bekerja sebagai racun kontak dan lambung, efektif mengendalikan wereng dan hama penghisap pada tanaman padi serta berbagai tanaman perkebunan seperti kopi, lada, dan teh.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('mipcin-500', 'Mipcinta 50 WP 500gr', 'insektisida', '500 gram', NULL, 'Insektisida untuk wereng coklat, walang sangit, dan hama penting tanaman padi.', 'MIPC (Isoprocarb) 50%', 'Wereng coklat, wereng hijau, walang sangit, kutu putih, dan penghisap daun pada padi, jagung, kedelai, kakao, kopi, lada, lamtoro, dan teh', 'Insektisida produksi Petrokimia Kayaku berbentuk tepung putih susu yang dapat disuspensikan (wettable powder). Bekerja sebagai racun kontak dan lambung, efektif mengendalikan wereng dan hama penghisap pada tanaman padi serta berbagai tanaman perkebunan seperti kopi, lada, dan teh.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('toxedown-100', 'Toxedown 150 EC 100ml', 'insektisida', '100 ml', 'images/produk/toxedown-100.webp', 'Insektisida dua bahan aktif untuk ulat krop, kutu daun, dan thrips.', 'Emamektin Benzoat 50 g/L + Lufenuron 100 g/L', 'Ulat krop, kutu daun, thrips pada kubis, jeruk, kacang panjang, tomat, kentang, cabai, bawang merah', 'Insektisida double action produksi CV Delta Chemica berbentuk pekatan berwarna kuning pucat yang dapat diemulsikan. Menggabungkan dua bahan aktif yang bekerja sinergis: Emamektin benzoat menyerang sistem saraf hama sehingga larva berhenti makan, sedangkan Lufenuron menghambat sintesis kitin sehingga menghentikan pertumbuhan dan siklus hidup hama.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('toxedown-250', 'Toxedown 150 EC 250ml', 'insektisida', '250 ml', 'images/produk/toxedown-250.webp', 'Insektisida dua bahan aktif untuk ulat krop, kutu daun, dan thrips.', 'Emamektin Benzoat 50 g/L + Lufenuron 100 g/L', 'Ulat krop, kutu daun, thrips pada kubis, jeruk, kacang panjang, tomat, kentang, cabai, bawang merah', 'Insektisida double action produksi CV Delta Chemica berbentuk pekatan berwarna kuning pucat yang dapat diemulsikan. Menggabungkan dua bahan aktif yang bekerja sinergis: Emamektin benzoat menyerang sistem saraf hama sehingga larva berhenti makan, sedangkan Lufenuron menghambat sintesis kitin sehingga menghentikan pertumbuhan dan siklus hidup hama.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('starlon-100', 'Starlon 665 EC 100ml', 'herbisida', '100 ml', 'images/produk/starlon-100.webp', 'Herbisida sistemik spesialis gulma berkayu dan tunggul pohon.', 'Triklopir Butoksi Etil Ester 665 g/L', 'Semak belukar, gulma berkayu, dan tunggul pohon pada kelapa sawit dan padi', 'Herbisida sistemik purna tumbuh produksi Nufarm, sangat efektif mengendalikan semak belukar, tunggul kayu, dan gulma berkayu. Bekerja meresap ke dalam jaringan kayu hingga ke akar sehingga tunggul pohon tidak tumbuh kembali. Dapat dicampur dengan herbisida glifosat atau parakuat untuk memperluas spektrum pengendalian, dan dapat diaplikasikan dengan cara semprot maupun oles pada tunggul.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('starlon-1l', 'Starlon 665 EC 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik spesialis gulma berkayu dan tunggul pohon.', 'Triklopir Butoksi Etil Ester 665 g/L', 'Semak belukar, gulma berkayu, dan tunggul pohon pada kelapa sawit dan padi', 'Herbisida sistemik purna tumbuh produksi Nufarm, sangat efektif mengendalikan semak belukar, tunggul kayu, dan gulma berkayu. Bekerja meresap ke dalam jaringan kayu hingga ke akar sehingga tunggul pohon tidak tumbuh kembali. Dapat dicampur dengan herbisida glifosat atau parakuat untuk memperluas spektrum pengendalian, dan dapat diaplikasikan dengan cara semprot maupun oles pada tunggul.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('garlon-100', 'Garlon 670 EC 100ml', 'herbisida', '100 ml', 'images/produk/garlon-100.webp', 'Herbisida sistemik spesialis mematikan pohon dan gulma berkayu.', 'Triklopir Butoksi Etil Ester 670 g/L (setara asam triklopir 480 g/L)', 'Semak belukar, gulma berkayu (anakan kayu), dan tunggul pohon pada karet dan kelapa sawit', 'Herbisida sistemik dengan konsentrasi triklopir tertinggi di pasaran, efektif mengendalikan gulma berkayu dan semak belukar tanpa menyebabkan parthenocarpy pada kelapa sawit. Dapat diaplikasikan dengan penyemprotan volume tinggi maupun dioleskan pada tunggul pohon (dicampur solar) untuk mencegah tunas baru tumbuh kembali.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('kresnaup-1l', 'Kresna Up 520 SL 1 Liter', 'herbisida', '1 liter', 'images/produk/kresnaup-combo.webp', 'Herbisida sistemik purna tumbuh untuk gulma berdaun lebar dan sempit.', 'IPA Glifosat 520 g/L', 'Gulma berdaun lebar dan sempit pada kelapa sawit belum menghasilkan (TBM)', 'Herbisida sistemik purna tumbuh produksi Sari Kresna Kimia, berbentuk larutan dalam air berwarna cokelat keemasan. Diserap melalui daun dan bekerja sistemik hingga ke akar gulma. Cocok digunakan pada perkebunan kelapa sawit yang belum menghasilkan (TBM).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('gibas-1l', 'Gibas 240 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma pada tanaman jagung.', 'IPA Glifosat 240 g/L', 'Gulma pada tanaman jagung (tanpa olah tanah/TOT)', 'Herbisida sistemik purna tumbuh produksi Sari Kresna Kimia, berbentuk larutan dalam air berwarna cokelat keemasan. Digunakan untuk mengendalikan gulma pada persiapan lahan budidaya tanaman jagung dengan sistem tanpa olah tanah (TOT).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('grasso-1l', 'Grasso 480 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma berdaun lebar, sempit, dan alang-alang.', 'IPA Glifosat 480 g/L', 'Gulma berdaun lebar, berdaun sempit, dan alang-alang (Imperata cylindrica) pada kelapa sawit menghasilkan (TM)', 'Herbisida sistemik purna tumbuh produksi Sari Kresna Kimia, berbentuk larutan dalam air berwarna kuning keemasan. Efektif mengendalikan gulma berdaun lebar seperti Mikania micrantha dan Ageratum conyzoides, gulma berdaun sempit seperti Axonopus compressus, serta alang-alang pada perkebunan kelapa sawit yang sudah menghasilkan (TM).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('jumpup-1l', 'Jump Up 555 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh konsentrasi tinggi untuk gulma pada sawit dan kakao.', 'IPA Glifosat 555 g/L', 'Gulma berdaun lebar dan berdaun sempit pada kelapa sawit dan kakao belum menghasilkan (TBM)', 'Herbisida sistemik purna tumbuh produksi Sari Kresna Kimia dengan konsentrasi glifosat tinggi, berbentuk larutan dalam air berwarna kuning keemasan. Digunakan untuk mengendalikan gulma berdaun lebar dan sempit pada budidaya kelapa sawit dan kakao yang belum menghasilkan (TBM).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('em4-1l', 'EM4 Pertanian 1 Liter', 'lainnya', '1 liter', NULL, 'Cairan mikroorganisme untuk menyuburkan tanah dan membuat pupuk organik.', 'Kultur mikroorganisme (bakteri fotosintetik, Lactobacillus, Actinomycetes, ragi/yeast)', 'Perbaikan kualitas tanah dan fermentasi bahan organik pada cabai, padi, sayuran, bawang merah, jagung, jeruk, dan tanaman perkebunan', 'Larutan konsentrat berisi campuran mikroorganisme hidup yang menguntungkan bagi kesuburan tanah dan pertumbuhan tanaman, ditemukan oleh Prof. Dr. Teruo Higa dari Jepang. EM4 mempercepat dekomposisi bahan organik menjadi pupuk (Bokashi), memperbaiki sifat fisik, kimia, dan biologi tanah, serta meningkatkan produksi tanaman secara alami dan ramah lingkungan. Sebelum digunakan, EM4 perlu diaktifkan dengan campuran molase/gula dan air.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('vampyr-100', 'Vampyr 700 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida dua bahan aktif untuk ulat grayak, thrips, dan kutu daun.', 'Klorfenapir 200 g/L + Asefat 500 g/L', 'Ulat grayak, thrips, kutu daun, dan lalat buah pada bawang merah, kubis, dan tanaman sayuran lainnya', 'Insektisida produksi Golden Farm Indonesia berbentuk pekatan berwarna kuning kecoklatan yang dapat diemulsikan, mengombinasikan dua bahan aktif. Bekerja dengan tiga mekanisme sekaligus: racun kontak, racun lambung, dan sebagian sistemik, sehingga efektif mengendalikan hama yang sudah resisten terhadap insektisida tunggal.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('vampyr-200', 'Vampyr 700 EC 200ml', 'insektisida', '200 ml', NULL, 'Insektisida dua bahan aktif untuk ulat grayak, thrips, dan kutu daun.', 'Klorfenapir 200 g/L + Asefat 500 g/L', 'Ulat grayak, thrips, kutu daun, dan lalat buah pada bawang merah, kubis, dan tanaman sayuran lainnya', 'Insektisida produksi Golden Farm Indonesia berbentuk pekatan berwarna kuning kecoklatan yang dapat diemulsikan, mengombinasikan dua bahan aktif. Bekerja dengan tiga mekanisme sekaligus: racun kontak, racun lambung, dan sebagian sistemik, sehingga efektif mengendalikan hama yang sudah resisten terhadap insektisida tunggal.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('rumpas-100', 'Rumpas 120 EW 100ml', 'herbisida', '100 ml', NULL, 'Herbisida kontak & sistemik cepat untuk gulma rumput pada padi dan sayuran.', 'Fenoksaprop-p-etil 120 g/L', 'Gulma rumput-rumputan (jawan, dengkulan, teki) pada padi sawah/gogo, bawang merah, cabai, kedelai, dan kacang-kacangan', 'Herbisida kontak dan sistemik purna tumbuh produksi Bayer, berbentuk emulsi minyak dalam air berwarna putih. Daya kerja sangat cepat, gulma berhenti tumbuh 2-3 hari setelah aplikasi dan mati total dalam 1-2 minggu. Efektif untuk gulma golongan rumput seperti Echinochloa dan Leptochloa pada padi sawah maupun gogo.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('kayabas-250', 'Kayabas 555 SC 250ml', 'herbisida', '250 ml', NULL, 'Herbisida pra & purna tumbuh untuk gulma pada tanaman jagung.', 'Atrazin 500 g/L + Mesotrion 55 g/L', 'Gulma berdaun sempit dan berdaun lebar pada tanaman jagung', 'Herbisida sistemik selektif produksi Petrokimia Kayaku, berbentuk pekatan suspensi berwarna putih kecoklatan, digunakan sebagai herbisida pra tumbuh dan awal purna tumbuh. Satu paket terdiri dari botol Kayabas dan botol surfaktan pendamping. Efektif mengendalikan gulma berdaun sempit (Brachiaria, Digitaria) dan berdaun lebar (Euphorbia, Commelina, Synedrella) pada budidaya jagung, cukup satu kali semprot per musim tanam.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('kayabas-500', 'Kayabas 555 SC 500ml', 'herbisida', '500 ml', NULL, 'Herbisida pra & purna tumbuh untuk gulma pada tanaman jagung.', 'Atrazin 500 g/L + Mesotrion 55 g/L', 'Gulma berdaun sempit dan berdaun lebar pada tanaman jagung', 'Herbisida sistemik selektif produksi Petrokimia Kayaku, berbentuk pekatan suspensi berwarna putih kecoklatan, digunakan sebagai herbisida pra tumbuh dan awal purna tumbuh. Satu paket terdiri dari botol Kayabas dan botol surfaktan pendamping. Efektif mengendalikan gulma berdaun sempit (Brachiaria, Digitaria) dan berdaun lebar (Euphorbia, Commelina, Synedrella) pada budidaya jagung, cukup satu kali semprot per musim tanam.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('santrel-500', 'Santrel 500 SL', 'zpt', '500 ml', NULL, 'Zat pengatur tumbuh untuk rangsang getah karet & percepat pemasakan buah.', 'Etefon 500 g/L', 'Getah/lateks pada tanaman karet; percepatan pemasakan buah pada nanas, apel, kopi, dan padi', 'Zat Pengatur Tumbuh (ZPT) produksi Santani berbentuk larutan, memiliki fungsi ganda sebagai perangsang sekaligus vitamin tanaman. Pada tanaman karet digunakan dengan cara dioleskan pada bidang sadap untuk merangsang keluarnya getah/lateks. Pada tanaman buah dan padi berfungsi mempercepat pemasakan buah serta meningkatkan jumlah gabah isi per malai.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('supremo-1l', 'Supremo 480 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma berdaun lebar dan sempit.', 'Isopropilamina Glifosat 480 g/L', 'Gulma berdaun lebar dan berdaun sempit pada lahan tanpa tanaman, karet, kelapa sawit (TBM), kakao, teh, dan kopi (TBM)', 'Herbisida sistemik purna tumbuh produksi PT Dharma Guna Wibawa, berbentuk larutan dalam air berwarna kekuningan. Mengendalikan gulma seperti Alternanthera sesilis, Commelina spp, Cleome asvera, Echinochloa colonum, dan Axonopus compressus pada lahan tanpa olah tanah maupun lahan bebas tanaman di perkebunan karet, sawit, kakao, teh, dan kopi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('okboss-1l', 'Ok Boss 540 SL 1 Liter', 'herbisida', '1 liter', 'images/produk/okboss-combo.webp', 'Herbisida sistemik purna tumbuh konsentrasi tinggi untuk gulma berdaun lebar dan sempit.', 'Isopropil Amina Glifosat 540 g/L', 'Gulma berdaun lebar dan berdaun sempit pada lahan perkebunan', 'Herbisida sistemik purna tumbuh dengan konsentrasi glifosat tinggi, berbentuk larutan dalam air. Bekerja diserap melalui daun dan disebarkan hingga ke akar gulma, efektif untuk mengendalikan gulma berdaun lebar maupun sempit yang mengganggu lahan perkebunan.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('bioup-1l', 'Bio Up 490 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma pada kelapa sawit.', 'IPA Glifosat 490 g/L', 'Gulma berdaun lebar (Ageratum conyzoides, Clidemia hirta) dan berdaun sempit (Axonopus compressus, Ottochloa nodosa) pada kelapa sawit', 'Herbisida sistemik purna tumbuh produksi Sari Kresna Kimia, berbentuk larutan dalam air berwarna kuning keemasan. Bekerja masuk ke jaringan gulma dan menghambat proses fotosintesis serta pertumbuhan sel, efektif mengendalikan gulma berdaun lebar dan sempit pada perkebunan kelapa sawit.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('mkppaktani-1kg', 'MKP Pak Tani 1kg', 'pupuk', '1 kg', NULL, 'Pupuk kristal fosfat & kalium tinggi untuk pembungaan dan pembuahan.', 'P2O5 (Fosfat) 52% + K2O (Kalium) 34%', 'Merangsang pembungaan, pembentukan buah, dan mencegah kerontokan bunga/buah pada padi, jagung, cabai, tomat, melon, semangka, dan tanaman buah lainnya', 'Pupuk Mono Kalium Fosfat (MKP) berbentuk kristal putih yang 100% larut dalam air, sehingga mudah diaplikasikan dengan cara ditabur, dikocor, disemprot, atau sistem hidroponik. Kandungan fosfor dan kalium yang tinggi sangat baik untuk fase generatif tanaman: merangsang pertumbuhan akar, mempercepat pembungaan, serta mencegah kerontokan bunga dan buah. Dapat juga dicampur dengan fungisida sistemik untuk meningkatkan efikasi pengendalian penyakit embun tepung (powdery mildew).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('mkppaktani-200g', 'MKP Pak Tani 200gr', 'pupuk', '200 gram', NULL, 'Pupuk kristal fosfat & kalium tinggi untuk pembungaan dan pembuahan.', 'P2O5 (Fosfat) 52% + K2O (Kalium) 34%', 'Merangsang pembungaan, pembentukan buah, dan mencegah kerontokan bunga/buah pada padi, jagung, cabai, tomat, melon, semangka, dan tanaman buah lainnya', 'Pupuk Mono Kalium Fosfat (MKP) berbentuk kristal putih yang 100% larut dalam air, sehingga mudah diaplikasikan dengan cara ditabur, dikocor, disemprot, atau sistem hidroponik. Kandungan fosfor dan kalium yang tinggi sangat baik untuk fase generatif tanaman: merangsang pertumbuhan akar, mempercepat pembungaan, serta mencegah kerontokan bunga dan buah. Dapat juga dicampur dengan fungisida sistemik untuk meningkatkan efikasi pengendalian penyakit embun tepung (powdery mildew).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('vikar-250', 'Vikar 10 SL 250ml', 'zpt', '250 ml', NULL, 'ZPT perangsang getah karet, memperlambat penyumbatan pembuluh lateks.', 'Etefon (golongan ZPT perangsang lateks)', 'Merangsang produksi getah/lateks pada tanaman karet tua dan muda', 'Zat Pengatur Tumbuh (ZPT) khusus tanaman karet berbentuk cairan berwarna hijau, dioleskan pada bidang sadap/toreh. Bekerja memperlambat penyumbatan pembuluh lateks sehingga getah mengalir lebih lama dan produksi karet meningkat. Juga membantu mencegah penyakit pada bidang sadap sehingga kesehatan bidang toreh tetap terjaga. Cocok digunakan pada pohon karet tua maupun muda.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('agus-100', 'Agus 500 SC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida kontak & sistemik untuk kutu kebul dan tungau.', 'Diafentiuron 500 g/L', 'Kutu kebul (Bemisia tabaci) dan tungau (Polyphagotarsonemus latus) pada cabai, tomat, kentang, kubis, apel, dan semangka', 'Insektisida produksi PT Advansia Indotani, berbentuk pekatan suspensi (Suspension Concentrate). Bekerja dengan cara menghambat proses metabolisme hama sehingga hama tidak dapat melakukan aktivitas normal dan mati, baik lewat kontak langsung maupun sistemik dalam jaringan tanaman. Direkomendasikan dirotasi dengan insektisida bahan aktif lain untuk mencegah resistensi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('agus-250', 'Agus 500 SC 250ml', 'insektisida', '250 ml', NULL, 'Insektisida kontak & sistemik untuk kutu kebul dan tungau.', 'Diafentiuron 500 g/L', 'Kutu kebul (Bemisia tabaci) dan tungau (Polyphagotarsonemus latus) pada cabai, tomat, kentang, kubis, apel, dan semangka', 'Insektisida produksi PT Advansia Indotani, berbentuk pekatan suspensi (Suspension Concentrate). Bekerja dengan cara menghambat proses metabolisme hama sehingga hama tidak dapat melakukan aktivitas normal dan mati, baik lewat kontak langsung maupun sistemik dalam jaringan tanaman. Direkomendasikan dirotasi dengan insektisida bahan aktif lain untuk mencegah resistensi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('macan-1l', 'Macan 338 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida kontak untuk gulma berdaun lebar dan rumput pada sawit.', 'Parakuat Diklorida 338 g/L', 'Gulma berdaun lebar dan gulma golongan rumput pada kelapa sawit (TBM)', 'Herbisida kontak purna tumbuh produksi Mahakam, berbentuk larutan dalam air. Langsung mematikan jaringan gulma yang terkena semprot, bereaksi cepat untuk gulma yang masih hijau dan belum berakar dalam. Cocok untuk persiapan lahan pada perkebunan kelapa sawit belum menghasilkan (TBM).');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('basis-1l', 'Basis 150 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida non-selektif kontak & sistemik untuk gulma pada sawit.', 'Amonium Glufosinat 150 g/L', 'Gulma berdaun lebar dan gulma golongan rumput pada kelapa sawit (TBM)', 'Herbisida non-selektif produksi CBA, bekerja secara kontak sekaligus sebagian sistemik, berbentuk larutan dalam air. Bahan aktif glufosinat-amonium menghambat enzim glutamin sintetase pada gulma. Efektif untuk gulma yang sudah resisten terhadap glifosat maupun parakuat, dan relatif aman untuk tanaman muda karena tidak menyebabkan parthenocarpy.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('wpgetah-250', 'WP Getah 250ml', 'zpt', '250 ml', NULL, 'ZPT perangsang getah karet, sejenis dengan Vikar.', 'Etefon (golongan ZPT perangsang lateks)', 'Merangsang produksi getah/lateks pada tanaman karet', 'Zat Pengatur Tumbuh (ZPT) untuk tanaman karet, dioleskan pada bidang sadap/toreh untuk merangsang keluarnya getah/lateks. Sejenis dengan produk perangsang getah karet lain seperti Vikar, bekerja memperlambat penyumbatan pembuluh lateks agar getah mengalir lebih lama dan produksi karet meningkat.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('meurtieur-100', 'Meurtieur 30 EC 100ml', 'insektisida', '100 ml', NULL, 'Insektisida racun kontak & lambung, tuntaskan ulat & telurnya.', 'Emamektin Benzoat 30 g/L', 'Ulat grayak beserta telurnya, hama pelipat daun, dan penggerek batang pada bawang merah, padi, dan jagung', 'Insektisida produksi PT Biotis Agrindo berbentuk cairan kental berwarna coklat tua, bekerja sebagai racun kontak dan lambung yang kuat serta dapat bertindak sebagai racun telur. Efektif menuntaskan ulat-ulat yang bandel/kebal, menurunkan kemampuan ulat bertelur hingga 90%, dan bekerja sebagai racun sistemik lokal (translaminar) sehingga mampu menjangkau ulat yang tersembunyi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('meurtieur-250', 'Meurtieur 30 EC 250ml', 'insektisida', '250 ml', 'images/produk/meurtieur-250.webp', 'Insektisida racun kontak & lambung, tuntaskan ulat & telurnya.', 'Emamektin Benzoat 30 g/L', 'Ulat grayak beserta telurnya, hama pelipat daun, dan penggerek batang pada bawang merah, padi, dan jagung', 'Insektisida produksi PT Biotis Agrindo berbentuk cairan kental berwarna coklat tua, bekerja sebagai racun kontak dan lambung yang kuat serta dapat bertindak sebagai racun telur. Efektif menuntaskan ulat-ulat yang bandel/kebal, menurunkan kemampuan ulat bertelur hingga 90%, dan bekerja sebagai racun sistemik lokal (translaminar) sehingga mampu menjangkau ulat yang tersembunyi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('meurtieur-500', 'Meurtieur 30 EC 500ml', 'insektisida', '500 ml', NULL, 'Insektisida racun kontak & lambung, tuntaskan ulat & telurnya.', 'Emamektin Benzoat 30 g/L', 'Ulat grayak beserta telurnya, hama pelipat daun, dan penggerek batang pada bawang merah, padi, dan jagung', 'Insektisida produksi PT Biotis Agrindo berbentuk cairan kental berwarna coklat tua, bekerja sebagai racun kontak dan lambung yang kuat serta dapat bertindak sebagai racun telur. Efektif menuntaskan ulat-ulat yang bandel/kebal, menurunkan kemampuan ulat bertelur hingga 90%, dan bekerja sebagai racun sistemik lokal (translaminar) sehingga mampu menjangkau ulat yang tersembunyi.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('tigatop-500', 'Tigatop 500ml', 'herbisida', '500 ml', NULL, 'Herbisida sistemik selektif 3 bahan aktif untuk gulma pada jagung.', 'Atrazine + Mesotrion + Nikosulfuron', 'Gulma berdaun sempit dan berdaun lebar pada tanaman jagung', 'Herbisida sistemik selektif produksi Mahakam dengan tiga bahan aktif sekaligus (Atrazine, Mesotrion, Nikosulfuron), dirancang khusus untuk tanaman jagung. Kombinasi tiga bahan aktif memperluas spektrum pengendalian gulma, termasuk gulma bandel golongan rumput dan berdaun lebar, tanpa merusak tanaman jagung itu sendiri.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('tigatop-1l', 'Tigatop 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik selektif 3 bahan aktif untuk gulma pada jagung.', 'Atrazine + Mesotrion + Nikosulfuron', 'Gulma berdaun sempit dan berdaun lebar pada tanaman jagung', 'Herbisida sistemik selektif produksi Mahakam dengan tiga bahan aktif sekaligus (Atrazine, Mesotrion, Nikosulfuron), dirancang khusus untuk tanaman jagung. Kombinasi tiga bahan aktif memperluas spektrum pengendalian gulma, termasuk gulma bandel golongan rumput dan berdaun lebar, tanpa merusak tanaman jagung itu sendiri.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('sofia-500', 'Sofia 500ml', 'herbisida', '500 ml', NULL, 'Herbisida sistemik selektif 3 bahan aktif untuk gulma pada jagung, sejenis Tigatop.', 'Atrazine + Mesotrion + Nikosulfuron', 'Gulma berdaun sempit dan berdaun lebar pada tanaman jagung', 'Herbisida sistemik selektif produksi PT Asiana Chemicalindo Lestari, sejenis dengan Tigatop dari segi kegunaan dan kombinasi tiga bahan aktif untuk tanaman jagung. Efektif mengendalikan gulma berdaun lebar dan berdaun sempit tanpa merusak tanaman jagung.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('ulate-100', 'Ulate 550 SL 100ml', 'insektisida', '100 ml', NULL, 'Insektisida translaminar dua bahan aktif untuk ulat grayak & penggulung daun.', 'Dimehypo 500 g/L + Emamektin Benzoat 50 g/L', 'Ulat grayak (Spodoptera exigua) dan ulat penggulung daun (Plutella xylostella) pada berbagai tanaman sayuran dan buah', 'Insektisida berbentuk pekatan berwarna kuning kecoklatan yang dapat diemulsikan, bekerja sebagai racun kontak dan lambung yang bersifat translaminar. Kombinasi dua bahan aktif membuatnya efektif mengendalikan hama ulat pada berbagai tanaman sayuran dan buah.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('ulate-250', 'Ulate 550 SL 250ml', 'insektisida', '250 ml', NULL, 'Insektisida translaminar dua bahan aktif untuk ulat grayak & penggulung daun.', 'Dimehypo 500 g/L + Emamektin Benzoat 50 g/L', 'Ulat grayak (Spodoptera exigua) dan ulat penggulung daun (Plutella xylostella) pada berbagai tanaman sayuran dan buah', 'Insektisida berbentuk pekatan berwarna kuning kecoklatan yang dapat diemulsikan, bekerja sebagai racun kontak dan lambung yang bersifat translaminar. Kombinasi dua bahan aktif membuatnya efektif mengendalikan hama ulat pada berbagai tanaman sayuran dan buah.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('rambogold-1l', 'Rambo Gold 480 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh untuk gulma hingga ke akar.', 'Isopropilamina Glifosat 480 g/L', 'Gulma berdaun lebar dan sempit pada jagung, kelapa sawit, karet, teh, dan lahan tanpa tanaman', 'Herbisida sistemik purna tumbuh berbentuk cairan berwarna kekuningan. Bekerja masuk ke jaringan gulma dan ditranslokasikan ke seluruh bagian gulma, menghambat pembentukan asam amino dan enzim EPSP sehingga gulma mati hingga ke akarnya. Daya bunuhnya relatif cepat dengan waktu tumbuh kembali (regrowth) yang lebih lambat dibanding produk glifosat sejenis.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('rambopeak-1l', 'Rambo Peak 555 SL 1 Liter', 'herbisida', '1 liter', NULL, 'Herbisida sistemik purna tumbuh konsentrasi tinggi untuk gulma hingga ke akar.', 'Isopropilamina Glifosat 555 g/L', 'Gulma berdaun lebar dan sempit pada jagung, kelapa sawit, karet, teh, dan lahan tanpa tanaman', 'Versi konsentrasi lebih tinggi dari Rambo Gold, herbisida sistemik purna tumbuh berbentuk cairan. Bekerja masuk ke jaringan gulma dan ditranslokasikan ke seluruh bagian gulma, menghambat pembentukan asam amino dan enzim EPSP sehingga gulma mati hingga ke akarnya. Konsentrasi bahan aktif yang lebih tinggi cocok untuk pengendalian gulma yang lebih bandel.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('powersoil-500', 'Power Soil 500gr', 'pupuk', '500 gram', NULL, 'Pembenah tanah asam humat untuk memperbaiki struktur & kesuburan tanah.', 'Asam Humat 60%, C-organik 15%, N 1%, P2O5 5,46%, K2O 1,08%', 'Memperbaiki struktur tanah dan meningkatkan efisiensi pemupukan pada padi, sayuran, buah-buahan, dan tanaman hias', 'Pupuk organik berbahan dasar asam humat, berbentuk tepung hitam yang larut dalam air. Berfungsi sebagai pembenah tanah yang memperbaiki Kapasitas Tukar Kation (KTK), meningkatkan kapasitas ikat air tanah sehingga mengurangi risiko kekeringan, serta melepaskan ion hara N, P, K yang terikat partikel tanah agar lebih mudah diserap tanaman. Dapat dicampur dengan pupuk makro (NPK), kalsium, kompos, maupun pestisida aplikasi tanah.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('powersoil-1kg', 'Power Soil 1kg', 'pupuk', '1 kg', NULL, 'Pembenah tanah asam humat untuk memperbaiki struktur & kesuburan tanah.', 'Asam Humat 60%, C-organik 15%, N 1%, P2O5 5,46%, K2O 1,08%', 'Memperbaiki struktur tanah dan meningkatkan efisiensi pemupukan pada padi, sayuran, buah-buahan, dan tanaman hias', 'Pupuk organik berbahan dasar asam humat, berbentuk tepung hitam yang larut dalam air. Berfungsi sebagai pembenah tanah yang memperbaiki Kapasitas Tukar Kation (KTK), meningkatkan kapasitas ikat air tanah sehingga mengurangi risiko kekeringan, serta melepaskan ion hara N, P, K yang terikat partikel tanah agar lebih mudah diserap tanaman. Dapat dicampur dengan pupuk makro (NPK), kalsium, kompos, maupun pestisida aplikasi tanah.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('primazeb-100', 'Primazeb 80 WP 100gr', 'fungisida', '100 gram', NULL, 'Fungisida kontak Mankozeb biru untuk penyakit jamur berbagai tanaman.', 'Mankozeb 80%', 'Busuk daun, bercak ungu, bercak daun, dan bercak kering pada padi, sayuran, buah-buahan, dan tanaman hortikultura', 'Fungisida kontak produksi Prima Karya berbentuk tepung berwarna biru kehijauan, bekerja dengan cara menghalangi respirasi jamur sehingga jamur tidak dapat berkembang lebih lanjut. Dilengkapi teknologi Rain Shield yang membuatnya tidak mudah tercuci air hujan setelah aplikasi, sehingga tetap efektif tanpa perlu tambahan bahan perekat.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('primazeb-800', 'Primazeb 80 WP 800gr', 'fungisida', '800 gram', NULL, 'Fungisida kontak Mankozeb biru untuk penyakit jamur berbagai tanaman.', 'Mankozeb 80%', 'Busuk daun, bercak ungu, bercak daun, dan bercak kering pada padi, sayuran, buah-buahan, dan tanaman hortikultura', 'Fungisida kontak produksi Prima Karya berbentuk tepung berwarna biru kehijauan, bekerja dengan cara menghalangi respirasi jamur sehingga jamur tidak dapat berkembang lebih lanjut. Dilengkapi teknologi Rain Shield yang membuatnya tidak mudah tercuci air hujan setelah aplikasi, sehingga tetap efektif tanpa perlu tambahan bahan perekat.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('bionm-500', 'Bion M 1/48 WP 500gr', 'fungisida', '500 gram', 'https://www.syngenta.co.id/sites/g/files/kgtney1281/files/styles/brand_logo/public/wysiwyg/image/sites/g/files/kgtney1281/files/styles/brand_logo/public/media/image/2023/03/14/bion_m_500g.jpg', 'Fungisida protektif ganda: kendalikan jamur & aktifkan daya tahan tanaman.', 'Asibenzolar-S-Metil 1% + Mankozeb 48%', 'Antraknosa/patek, busuk buah, busuk kering, busuk basah, bercak daun, dan busuk Phytophthora pada cabai, kentang, kubis, dan tomat', 'Fungisida protektif produksi Syngenta berbentuk tepung coklat kekuningan yang dapat disuspensikan, bekerja sistemik dan kontak sekaligus. Keunggulannya ada pada kombinasi dua bahan aktif: Mankozeb yang mengendalikan cendawan secara langsung, dan Asibenzolar-S-Metil yang bekerja mengaktifkan ketahanan alami tanaman terhadap penyakit (bukan membunuh patogen secara langsung), sehingga memberikan perlindungan ganda.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('kresnaup-5l', 'Kresna Up 520 SL 5 Liter', 'herbisida', '5 liter', 'images/produk/kresnaup-combo.webp', 'Herbisida sistemik purna tumbuh untuk gulma berdaun lebar dan sempit.', 'IPA Glifosat 520 g/L', 'Gulma berdaun lebar dan sempit pada kelapa sawit belum menghasilkan (TBM)', 'Herbisida sistemik purna tumbuh produksi Sari Kresna Kimia, berbentuk larutan dalam air berwarna cokelat keemasan. Diserap melalui daun dan bekerja sistemik hingga ke akar gulma. Cocok digunakan pada perkebunan kelapa sawit yang belum menghasilkan (TBM). Kemasan 5 liter untuk kebutuhan penyemprotan area lebih luas.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('okboss-5l', 'Ok Boss 540 SL 5 Liter', 'herbisida', '5 liter', 'images/produk/okboss-combo.webp', 'Herbisida sistemik purna tumbuh konsentrasi tinggi untuk gulma berdaun lebar dan sempit.', 'Isopropil Amina Glifosat 540 g/L', 'Gulma berdaun lebar dan berdaun sempit pada lahan perkebunan', 'Herbisida sistemik purna tumbuh dengan konsentrasi glifosat tinggi, berbentuk larutan dalam air. Bekerja diserap melalui daun dan disebarkan hingga ke akar gulma, efektif untuk mengendalikan gulma berdaun lebar maupun sempit yang mengganggu lahan perkebunan. Kemasan 5 liter untuk kebutuhan penyemprotan area lebih luas.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('gramoxone-1l', 'Gramoxone 276 SL 1 Liter', 'herbisida', '1 liter', 'images/produk/gramoxone-combo.webp', 'Herbisida kontak purna tumbuh spektrum luas untuk berbagai jenis tanaman.', 'Parakuat Diklorida 276 g/L (setara ion parakuat 200 g/L)', 'Anakan sawit liar, gulma berdaun lebar, sempit, dan teki pada berbagai tanaman', 'Herbisida produksi Syngenta yang bekerja secara kontak purna tumbuh, berbentuk larutan dalam air berwarna hijau tua. Mengendalikan anakan sawit liar serta gulma berdaun lebar, sempit, dan teki di lahan tanpa tanaman maupun di sela tanaman perkebunan (karet, kelapa sawit, kopi, tebu, teh) dan tanaman pangan (jagung, padi gogo, kedelai, kentang, kubis, tomat) serta tanaman buah. Hanya digunakan oleh pengguna bersertifikat.');
insert into products (id, name, cat, size, img, description, active_ingredient, target, long_desc) values ('gempur-1l', 'Gempur 480 SL 1 Liter', 'herbisida', '1 liter', 'images/produk/gempur-combo.webp', 'Herbisida sistemik purna tumbuh untuk gulma di lahan perkebunan & persiapan lahan.', 'Isopropil Amina Glifosat 480 g/L (setara Glifosat 356 g/L)', 'Gulma pada hutan tanaman industri, kakao, karet, kelapa sawit, kopi, teh, dan persiapan lahan jagung (TOT)', 'Herbisida sistemik purna tumbuh berbentuk larutan yang dapat larut dalam air, berwarna kuning kecoklatan. Digunakan untuk mengendalikan gulma pada hutan tanaman industri (Acacia mangium), perkebunan kakao, karet, kelapa sawit, kopi, teh, serta persiapan lahan budidaya jagung tanpa olah tanah.');
